import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("MHPCO quote — base premiums", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("single sword → premium 105 G (100 base + 5 fee)");
  it.todo("single amulet → premium 65 G (60 base + 5 fee)");
  it.todo("single staff → premium 85 G (80 base + 5 fee)");
  it.todo("single potion → premium 45 G (40 base + 5 fee)");
  it.todo("single rune (component) → premium 30 G (25 base + 5 fee)");
  it.todo("single moonstone (component) → premium 30 G (25 base + 5 fee)");
});

describe("MHPCO quote — building block of 3 alike components", () => {
  it.todo("2 runes → 50 G base premium (+5 fee = 55 G)");
  it.todo("3 runes → 60 G base premium, block applies (+5 fee = 65 G)");
  it.todo("4 runes → 100 G base premium, no block (+5 fee = 105 G)");
  it.todo("7 runes → 175 G base premium (+5 fee = 180 G)");
  it.todo("2 runes + 1 moonstone → 75 G base premium, no block: different types (+5 fee = 80 G)");
  it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (+5 fee = 125 G)");
});

describe("MHPCO quote — item-specific modifiers", () => {
  it.todo("cursed sword → 100 base + 50 curse surcharge (+5 fee = 155 G)");
  it.todo("sword enchantment 5 → high-enchantment surcharge 30 (+5 fee = 135 G)");
  it.todo("sword enchantment 4 → no high-enchantment surcharge (+5 fee = 105 G)");
  it.todo("cursed sword enchantment 5 → both surcharges: 100 + 50 + 30 (+5 fee = 185 G)");
});

describe("MHPCO quote — policy-wide modifiers", () => {
  it.todo("cursed sword + plain amulet → 160 base + 50 curse (of sword) = 210 G before fee (+5 fee = 215 G)");
  it.todo("customer with exactly 2 years → 20% loyalty discount applies");
  it.todo("first insurance carries 10% initial assessment surcharge (per item)");
  it.todo("follow-up contract (second quote) gets 15% discount");
});

describe("MHPCO quote — rounding in MHPCO's favor", () => {
  it.todo("premium yielding 197.5 G → 198 G (rounded up)");
});

describe("MHPCO quote — integration examples", () => {
  it.todo("newcomer with cursed sword (0 yrs, steel, ench 3) → 165 G");
  it.todo("long-standing customer's second contract (3 yrs, cursed sword ench 7) → 160 G");
});

describe("MHPCO quote — edge cases", () => {
  it.todo("unknown item type → throws / error");
});

describe("MHPCO claim — standard reimbursement", () => {
  it.todo("regular sword (steel, ench 3), damage 500 G → payout 400 G (500 - 100 deductible)");
  it.todo("rune (value 250 G), damage 200 G → payout 100 G (200 - 100 deductible)");
});

describe("MHPCO claim — special clauses", () => {
  it.todo("item enchantment ≥ 8 reimbursed at 50% then deductible");
  it.todo("dragon-material item fully reimbursed then deductible");
  it.todo("dragon sword ench 8, damage 1000 → payout 400 (50% clause wins, then deductible)");
  it.todo("dragon sword ench 9, damage 1000 → payout 400 (both apply, 50% wins, then deductible)");
  it.todo("dragon sword ench 5, damage 800 → payout 700 (only dragon clause, then deductible)");
  it.todo("steel sword ench 9, damage 1000 → payout 400 (only high-ench clause: 50% then deductible)");
});

describe("MHPCO claim — deductible per damage event", () => {
  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 (deductible once per item)");
});

describe("MHPCO claim — cap", () => {
  it.todo("policy of two swords → insurance sum 2000, cap 4000");
  it.todo("cursed sword (modified premium) → cap 2000 based on unmodified insurance value");
  it.todo("sword + 3 runes block → insurance sum 1750, cap based on unmodified values");
  it.todo("sword cap 2000: first claim 1500 → payout 1400, remaining 600");
  it.todo("sword cap 2000: second claim 1500 → payout 600, remaining 0 (reduced to remaining cap)");
});

describe("MHPCO claim — multiple items of same type", () => {
  it.todo("two sword damages both insured → each its own deductible");
  it.todo("more damages of a type than insured → error (claim rejected)");
});

describe("MHPCO claim — rounding in MHPCO's favor", () => {
  it.todo("payout yielding 350.5 G → 350 G (rounded down)");
});

describe("MHPCO claim — edge cases", () => {
  it.todo("damage entry for item not in policy → error");
  it.todo("damage entry with negative amount → error");
});

