    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], 0)).toBe(65);
  });
  it("single staff → premium 85 G (80 base + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }], 0)).toBe(85);
