  it("single potion → premium 45 G (40 base + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }], 0)).toBe(45);
  });
  it("single rune (component) → premium 30 G (25 base + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }], 0)).toBe(30);
  });
  it("single moonstone (component) → premium 30 G (25 base + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }], 0)).toBe(30);
  });
});

