    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }], 0)).toBe(55);
  });
  it("3 runes → 60 G base premium, block applies (+5 fee = 65 G)", () => {
    expect(
      quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }, { type: "rune" }], 0),
    ).toBe(65);
  });
  it("4 runes → 100 G base premium, no block (+5 fee = 105 G)", () => {
    expect(
      quote({ yearsWithMHPCO: 0 }, Array(4).fill({ type: "rune" }), 0),
    ).toBe(105);
  });
  it("7 runes → 175 G base premium (+5 fee = 180 G)", () => {
    expect(
      quote({ yearsWithMHPCO: 0 }, Array(7).fill({ type: "rune" }), 0),
    ).toBe(180);
  });
  it("2 runes + 1 moonstone → 75 G base premium, no block: different types (+5 fee = 80 G)", () => {
    expect(
      quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }], 0),
