    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }], 0)).toBe(155);
  });
  it("sword enchantment 5 → high-enchantment surcharge 30 (+5 fee = 135 G)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5 }], 0)).toBe(135);
  });
  it("sword enchantment 4 → no high-enchantment surcharge (+5 fee = 105 G)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 4 }], 0)).toBe(105);
  });
  it("cursed sword enchantment 5 → both surcharges: 100 + 50 + 30 (+5 fee = 185 G)", () => {
