    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }], 0)).toBe(33);
  });
  it("single moonstone (component) → premium 33 G (25 base + 2.5 first-ins + 5 fee = 32.5 → 33)", () => {
